pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    // Unfold the definitions of `always` and `and` and compare the resulting predicates.
    //
    // always(p.and(q))  = TempPred::new(|ex| forall i, (p& q)(ex.suffix(i)))
    //                   = TempPred::new(|ex| forall i, p(ex.suffix(i)) && q(ex.suffix(i)))
    // always(p).and(always(q)) = TempPred::new(|ex| (forall i, p(ex.suffix(i))) &&
    //                                            (forall i, q(ex.suffix(i))))
    //                   = TempPred::new(|ex| forall i, p(ex.suffix(i)) && q(ex.suffix(i)))
    //
    // We prove extensional equality via mutual entailment.

    let r1: TempPred<T> = always(p.and(q));
    let r2: TempPred<T> = always(p).and(always(q));

    assert r1.entails(r2) by {
        assert forall|ex: Execution<T>| r1.satisfied_by(ex) implies r2.satisfied_by(ex) by {
            forall |ex: Execution<T>| {
                assume( r1.satisfied_by(ex) );
            }
        }
    };
}

